import { AudioPlayer, createAudioPlayer, setAudioModeAsync } from 'expo-audio';

/** Generated by scripts/generate-sounds.mjs — original, soft, low-key (PRD §9). */
const SOURCES = {
  tap: require('../../assets/sounds/tap.wav'),
  whoosh: require('../../assets/sounds/whoosh.wav'),
  bounce: require('../../assets/sounds/bounce.wav'),
  heart: require('../../assets/sounds/heart.wav'),
  chime: require('../../assets/sounds/chime.wav'),
};
const MUSIC = require('../../assets/sounds/ambient.wav');

export type Sfx = keyof typeof SOURCES;

class AudioService {
  private players = new Map<Sfx, AudioPlayer>();
  private music: AudioPlayer | null = null;
  private soundOn = true;
  private musicOn = true;
  private ready = false;

  private init() {
    if (this.ready) return;
    this.ready = true;
    // Respect the silent switch and never interrupt the player's own music.
    setAudioModeAsync({ playsInSilentMode: false, interruptionMode: 'mixWithOthers' }).catch(() => {});
  }

  configure(sound: boolean, music: boolean) {
    this.init();
    this.soundOn = sound;
    this.musicOn = music;
    if (music) {
      if (!this.music) {
        this.music = createAudioPlayer(MUSIC);
        this.music.loop = true;
        this.music.volume = 0.25;
      }
      this.music.play();
    } else {
      this.music?.pause();
    }
  }

  play(name: Sfx) {
    if (!this.soundOn) return;
    let player = this.players.get(name);
    if (!player) {
      player = createAudioPlayer(SOURCES[name]);
      player.volume = 0.6;
      this.players.set(name, player);
    }
    player.seekTo(0).catch(() => {});
    player.play();
  }
}

export const audio = new AudioService();
